          "detailMarkdown": "## 2367 燿華 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026/1Q 各地產能：約 **台灣 130萬呎/月、南通 80萬呎/月、泰國 20萬呎/月**；泰國廠目前仍在爬坡。\n- 2026/1Q 產品結構中，技術面以 **HDI 56%**、**軟硬板 22%**、**傳統板 13%**、**高頻板 7%** 為主。\n- 應用面 2026/1Q 以 **汽車 36%**、**IT 31%**、**LEO 19%** 為主；管理層口述稱今年上半年 LEO 約 **15%~20%**。\n- 口述提到 **2026年第一季營業額約 38.98 億元**，並說明低於過往單季約 40 億元以上水準。\n- 原物料面臨 **PP、CCL** 供應偏緊與價格上升，對消費性產品與排程造成壓力。\n\n### 展望與成長利基\n- 公司預期 **泰國廠** 於第三季正式投產後，可逐步增加 LEO 相關出貨，並作為海外供應鏈基地。\n- **南通B棟** 主要投入 **光模組/AI相關板**，口述提及明年第二季起有機會明顯放量。\n- 管理層表示 **AI伺服器、高速傳輸、光通訊模組** 為未來成長重點，並透過 HLC/HDI 切入供應鏈。\n- **LEO** 由地面接收端逐步延伸至衛星本體相關應用，已進入樣品開發與量產擴張階段。\n- 管理層認為中長期仍可受惠於 **China+1**、東南亞供應鏈區域化趨勢。\n\n### 產品、客戶與市場位置\n- 公司說明目前營運主軸為 **LEO低軌衛星、AI基礎建設、光模組、高階HDI/HLC、汽車與消費性應用**。\n- 會中多次提及市場需求由傳統消費電子轉向 **AI、高速網通、衛星通訊** 等高附加價值應用。\n- 管理層表示目前營運仍受 **原物料供應與價格波動**、客戶拉貨節奏影響。\n- 2026/1Q 產品結構中，技術面以 **HDI 56%**、**軟硬板 22%**、**傳統板 13%**、**高頻板 7%** 為主。\n- 原物料面臨 **PP、CCL** 供應偏緊與價格上升，對消費性產品與排程造成壓力。\n- **南通B棟** 主要投入 **光模組/AI相關板**，口述提及明年第二季起有機會明顯放量。\n\n### 風險與不確定性\n- **原物料供應不穩**：口述指出目前較緊缺的主要是 **PP 與 CCL**，可能影響交期與成本。\n- **客戶拉貨遞延**：部分 LEO 客戶因內部調整、規格變動或排程因素，出貨節奏往後遞延。\n- **產能爬坡風險**：泰國廠與南通B棟均屬新產線，仍需時間完成 learning curve 與設備調整。\n- **市場復甦不均**：汽車與消費性電子短期仍受庫存調整與終端需求影響。\n- **技術轉換挑戰**：高層數板、厚板與高可靠度產品對製程、良率與設備有更高要求。\n- **需人工確認**：簡報第4頁寫泰國工廠地點為 **Ang Thong**，但口述多次提到 **紅統府**；兩者中文對應可能一致，建議確認正式地名譯法。\n- **需人工確認**：簡報第4頁寫泰國產能 **200K SF/月**，口述曾說「到明年第一季會達到20萬呎」，與簡報一致，但亦有提到泰國廠第三季正式投產，時間節點需再核對。\n- **需人工確認**：口述提到 2026年第一季營收 **38.98 億**，簡報未見對應數字頁面，需以財報或完整簡報頁確認。\n\n### Q&A 與管理層口氣\n- LEO營收占比：管理層口述今年上半年約 **15%~20%**，全年目標提到希望提高到 **30%** 左右。\n- 泰國廠量產進度：口述表示第二季小量試產，第三季正式放量；**20萬呎/月** 為第一階段目標。\n- 南通B棟用途：以 **光模組** 為主，A棟偏既有產線，B棟用於較新製程與較高階產品。\n- 光模組/AI產品占比：口述提到明年 AI 與光模組合計可能先落在 **5%~10%** 區間，光模組若順利則可接近 **10%**。\n- 會中說明高層數板技術可達 **14層、16層、22層** 等，重點不在層數而在 **板厚與良率**。\n\n### 評分利基點\n- 加分主因：公司說明目前營運主軸為 **LEO低軌衛星、AI基礎建設、光模組、高階HDI/HLC、汽車與消費性應用**。；管理層提到產能擴充重點在 **南通B棟** 與 **泰國廠**，下半年至明年第一季陸續開出新產能。；會中多次提及市場需求由傳統消費電子轉向 **AI、高速網通、衛星通訊** 等高附加價值應用。。\n- 扣分或保留：**原物料供應不穩**：口述指出目前較緊缺的主要是 **PP 與 CCL**，可能影響交期與成本。；**客戶拉貨遞延**：部分 LEO 客戶因內部調整、規格變動或排程因素，出貨節奏往後遞延。；**產能爬坡風險**：泰國廠與南通B棟均屬新產線，仍需時間完成 learning curve 與設備調整。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
