          "detailMarkdown": "## 1710 東聯 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 合併營收約 53.5 億元，連續數季維持單季 50 億元以上水準。\n- 2026Q1 歸屬東聯合併損失約 1.3 億元，EPS 為 -0.15 元；管理層提到虧損較 2025Q3、Q4 已有縮小。\n- 三大事業營收比重約為：乙二醇 61%、特化 31%、氣體 8%。\n- 2026/3/31 合併總資產約 369 億元，負債 237 億元，權益 132 億元，權益比 36%，每股淨值 12.4 元。\n- 轉錄中曾提及 2026Q1 營收「53.46 億元」、虧損「1.77 億元」與簡報中的 53.5 億、-1.3 億不一致，已列入交叉核對。\n- 2025 年現金股利為 0.00 元，簡報同時列示 2023 年股利 0.20 元、2024/2025 年為 0.00 元。\n\n### 展望與成長利基\n- 乙二醇相關原料與產品價格隨地緣事件波動，管理層認為後續市場仍可能受油價、供給與需求節奏影響。\n- 電子級溶劑與半導體用配方持續擴展，轉錄提到 DB 月銷售量約 160 噸，並期待隨客戶擴線而成長。\n- 新產品布局聚焦高速基板、半導體清洗劑、儲能電池電解液、精準 UV 光固化樹脂與高階電子材料。\n- 綠色化學方向包含 CO2 捕捉、CO2 衍生化學品、水泥爐石資源再利用等，強調循環經濟與減碳應用。\n- 管理層表示部分電子級、半導體相關產品已進入與客戶的保密協商或開發階段。\n- [需人工確認] 轉錄提到「今年度是半導體元年」屬管理層口語表述，非簡報正式用語。\n\n### 產品、客戶與市場位置\n- 公司主軸仍分為乙二醇事業、氣體事業與特用化學事業，並延續往半導體、電子材料與綠色化學方向轉型。\n- 管理層將 2026 年定位為「半導體元年」，強調電子級溶劑、EOD 衍生品、AI 應用材料與 CCU/CO2 相關布局。\n- 乙二醇相關原料與產品價格隨地緣事件波動，管理層認為後續市場仍可能受油價、供給與需求節奏影響。\n- 電子級溶劑與半導體用配方持續擴展，轉錄提到 DB 月銷售量約 160 噸，並期待隨客戶擴線而成長。\n- 新產品布局聚焦高速基板、半導體清洗劑、儲能電池電解液、精準 UV 光固化樹脂與高階電子材料。\n- 管理層表示部分電子級、半導體相關產品已進入與客戶的保密協商或開發階段。\n\n### 風險與不確定性\n- 簡報明確揭露未發布財務預測，未來成果可能受市場需求、價格波動、競爭、國際經濟、匯率與供應鏈影響。\n- 乙烯、原油與 MEG 價格變動對獲利影響顯著，且下游價格反應具有落後性。\n- 乙二醇仍面臨供過於求與外部進口競爭壓力，尤其中國大陸及區域市場供需變化具不確定性。\n- 半導體/電子材料布局多處於開發、協商或初期放量階段，後續量產與客戶導入時程未定。\n- 氣體五廠、原有場地再利用等規劃仍在進行中，實際效益與時間表尚未完全揭露。\n- [需人工確認] 轉錄中提及「美伊戰爭」、「60天觀察期」等地緣政治敘述，與正式簡報未逐項對應，且可能存在口語化或誤述。\n- 簡報頁面顯示本次為 2026.06 法說；轉錄開場卻提到「2022年第二季」與過往會議內容，推定為轉錄誤植或混入舊稿，需人工確認。\n- 簡報 2026Q1：營收 53.46 億、歸屬損失 1.27 億、EPS -0.15；轉錄曾說營收 53.46 億但損失 1.77 億，數字不一致，需人工確認。\n\n### Q&A 與管理層口氣\n- Q：電子級溶劑成長規劃？A：目前三項產品合計約每月 400 噸，DB 成長性較高，目標有機會較現階段成長逾 100%。\n- Q：EOD/特化產品後續方向？A：主要聚焦高速基板、半導體清洗劑、儲能電池電解液、精細界面活性劑等。\n- Q：大宗產品客戶與用途？A：EG 主要供國內化纖廠；EO 供內部自用及少數外部客戶；EA/EB/DB/EC/EOD 及氣體產品則分布於塗料、面板、半導體、電池、日化與工業用等。\n- Q：原有氣體廠場地後續用途？A：氣五廠完成後，氣二廠將拆除、氣三廠保留備用；多出土地目前尚在規劃中。\n- Q：半導體/面板用清洗配方是否有多家來源？A：工業級原料有多個供應來源，東聯並非唯一；電子級/半導體用途則聚焦 DB 等產品。\n- [需人工確認] 轉錄中多次出現「EA/EB/DB」「DB」「BCS」「TB/PB」等產品代稱，部分與簡報既有分類（EA、EB、EC、EOD、PEA、EDA）並列，可能需確認口語縮寫與正式產品名稱。\n\n### 評分利基點\n- 加分主因：會中提到 2025 年完成高雄乙烯儲槽、2026 年完成高雄液氨儲槽，有助原料取得彈性與成本管理。；管理層將 2026 年定位為「半導體元年」，強調電子級溶劑、EOD 衍生品、AI 應用材料與 CCU/CO2 相關布局。；氣體五廠預計於 2026 年底啟動投產，目標取代效率較低的氣二廠、氣三廠並提升產量與節能效益。。\n- 扣分或保留：簡報明確揭露未發布財務預測，未來成果可能受市場需求、價格波動、競爭、國際經濟、匯率與供應鏈影響。；乙烯、原油與 MEG 價格變動對獲利影響顯著，且下游價格反應具有落後性。；乙二醇仍面臨供過於求與外部進口競爭壓力，尤其中國大陸及區域市場供需變化具不確定性。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
