          "detailMarkdown": "## 9802 鈺齊-KY 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（44 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 0、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026Q1 合併營收為新台幣 36.75 億元，較 2025Q4 的 45.76 億元下滑；較 2025Q1 3.668 億元幾乎持平。\n- 2026Q1 營業毛利為 5,830 萬元，營業利益為 1.89 億元；營業利益率 5.2%，低於 2025Q1 的 7.6%。\n- 2026Q1 毛利率為 15.9%，較 2025Q4 的 18.1% 及 2025Q1 的 19.1% 下降。\n- 2025 年全年合併營收為 172.95 億元，營業毛利 31.63 億元，營業利益 21.13 億元。\n- 2025 年 EPS 為 6.05 元；2026Q1 EPS 為 0.89 元。\n- 銷售地區以歐洲、亞洲及美洲為主；2026Q1 歐洲占比 45.65%、亞洲 33.32%、美洲 13.27%。\n\n### 展望與成長利基\n- 公司簡報指出，運動休閒結合戶外時尚（Athleisure）為市場趨勢，預期帶動未來銷售成長動能。\n- 產品開發方向涵蓋 Outdoor Performance、Casual、Sports、Trail Running、Winter Boots、Snowboard Boots、Multi-functional Shoes 與 Vulcanized。\n- 公司與 50 餘個品牌合作，顯示客戶組合具一定廣度。\n- 簡報提到 GORE-TEX SURROUND® 等技術應用，強調透氣、防水與戶外機能。\n- 未揭露具體 2026 年全年營運目標或財務指引。\n\n### 產品、客戶與市場位置\n- 本次為鈺齊-KY受中國信託證券邀請之法人說明會，內容以公司財務與業務概況說明為主。\n- 簡報重點聚焦於公司沿革、全球產能布局、品牌合作版圖、產品開發方向與財務表現。\n- 簡報顯示公司自 1995 年成立，已在中國、越南、柬埔寨、印尼設有生產基地。\n- 銷售地區以歐洲、亞洲及美洲為主；2026Q1 歐洲占比 45.65%、亞洲 33.32%、美洲 13.27%。\n- 公司簡報指出，運動休閒結合戶外時尚（Athleisure）為市場趨勢，預期帶動未來銷售成長動能。\n- 產品開發方向涵蓋 Outdoor Performance、Casual、Sports、Trail Running、Winter Boots、Snowboard Boots、Multi-functional Shoes 與 Vulcanized。\n\n### 風險與不確定性\n- 簡報含有免責聲明，明示前瞻性資訊可能因外部風險、假設差異而與實際結果不同。\n- 營收受季節交替、營收認列時點與產能調配影響，月/季波動可能較明顯。\n- 海外產能分布涵蓋多國，涉及匯率、地緣政治、供應鏈與產地調整等不確定性。\n- 2026Q1 毛利率與營業利益率下滑，顯示成本結構與產品組合仍有變動。\n- 未揭露原物料價格、匯率或關稅等更細部風險說明。\n- 簡報第 21 頁與第 23 頁的 2025 年 EPS/ROE/ROA 圖表數值呈現方式略有不同；**需人工確認**是否為圖表縮放或欄位標示差異。\n- 第 25 頁股利頁面的「年度配發率」文字排版疑似斷裂，出現「2584.3%」等不合理串接；**需人工確認**原始數值與格式。\n- 第 12 頁各國產能圖的數字與括號百分比排列較密集，部分標示不易辨識；**需人工確認**中國、越南、柬埔寨、印尼對應數值。\n\n### Q&A 與管理層口氣\n- 簡報重點聚焦於公司沿革、全球產能布局、品牌合作版圖、產品開發方向與財務表現。\n- 2026Q1 毛利率為 15.9%，較 2025Q4 的 18.1% 及 2025Q1 的 19.1% 下降。\n- 營收受季節交替、營收認列時點與產能調配影響，月/季波動可能較明顯。\n- 海外產能分布涵蓋多國，涉及匯率、地緣政治、供應鏈與產地調整等不確定性。\n- 2026Q1 毛利率與營業利益率下滑，顯示成本結構與產品組合仍有變動。\n- 未揭露原物料價格、匯率或關稅等更細部風險說明。\n\n### 評分利基點\n- 加分主因：公司簡報指出，運動休閒結合戶外時尚（Athleisure）為市場趨勢，預期帶動未來銷售成長動能。；簡報提到 GORE-TEX SURROUND® 等技術應用，強調透氣、防水與戶外機能。。\n- 扣分或保留：簡報含有免責聲明，明示前瞻性資訊可能因外部風險、假設差異而與實際結果不同。；營收受季節交替、營收認列時點與產能調配影響，月/季波動可能較明顯。；海外產能分布涵蓋多國，涉及匯率、地緣政治、供應鏈與產地調整等不確定性。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
