          "detailMarkdown": "## 6016 康和證 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026/03/31 合併資產總計 **594.09 億元**，較 2025 年底增加；權益總計 **124.50 億元**，每股淨值 **18.03 元**。\n- 2026Q1 合併稅後淨利 **11.33 億元**，EPS **1.65 元**；去年同期為虧損。\n- 2026Q1 營業收益 **23.43 億元**，年增幅度明顯；營業費用 **11.70 億元**。\n- 2026/4 自結稅後淨利 **19.30 億元**，1-4 月累計稅後淨利 **30.63 億元**，EPS **4.46 元**。\n- 2025 年全年稅後淨利 **13.63 億元**，EPS **1.98 元**；股利發放率 **70.79%**。\n\n### 展望與成長利基\n- 簡報未揭露具體財測、年度營收/獲利目標或明確展望數字。\n- 從業務結構看，自營與經紀仍為主要獲利來源，後續重點可能仍在交易與資產配置相關收入。\n- 公司持續推動資安與制度強化，顯示以營運韌性與內控治理為主軸。\n- 承銷件數、債券市占等指標已有波動，後續表現仍待後續期間驗證。\n- 未揭露對景氣、利率或市場成交量的具體預測。\n\n### 產品、客戶與市場位置\n- 簡報揭露多項獎項與外部肯定，涵蓋數位金融、ESG、客戶信賴與品牌評比。\n- 未揭露對景氣、利率或市場成交量的具體預測。\n- 簡報聲明指出，內容含前瞻性陳述，實際結果可能受**政治、經濟、市場**等因素影響。\n- 2026Q1 衍生工具損益為負，顯示市場波動仍可能影響整體損益表現。\n\n### 風險與不確定性\n- 簡報聲明指出，內容含前瞻性陳述，實際結果可能受**政治、經濟、市場**等因素影響。\n- 2026Q1 衍生工具損益為負，顯示市場波動仍可能影響整體損益表現。\n- 市占率部分項目下滑，包含經紀、電子交易、期貨IB與債券等，競爭壓力仍在。\n- 股利結構高度依賴股票股利，未來配發方式與比率可能變動。\n- 簡報亦提醒部分非財務資訊未經會計師或獨立第三方審核。\n- **需人工確認**：MOPS 擇要寫「**115年度第一次線上法說會**」，簡報日期為 **115年06月**，兩者一致但與外部公告口徑仍建議再核對。\n- **需人工確認**：簡報同時出現 **2026Q1**、**2026/4** 與 **115年06月** 等時間標示；因轉錄未提供，建議確認是否皆為同一場法說會資料。\n- **需人工確認**：簡報第 7 頁「**債券市占率 2026(Mar.) 0.22%**」與前期 0.76%/0.78% 落差較大，應確認是否為口徑變更或統計基期不同。\n\n### Q&A 與管理層口氣\n- 簡報末頁僅列 **Q&A**，未提供問答逐字內容。\n- 奬項與肯定：包含 ISO 27001:2022 轉版、幸福企業金獎、最佳財富增值獎、反詐騙 MOU 等。\n- 集團形象與ESG/數位金融相關揭露篇幅較多，反映非財務治理與品牌經營比重。\n- 未揭露法人提問內容、管理階層回答或後續補充說明。\n\n### 評分利基點\n- 加分主因：集團持續強調**資安治理**，並將 ISO 27001:2022 轉版驗證範圍擴大至康和期貨。；2025 年盈餘配發維持高配發率，惟股利組成以**股票股利**占比偏高。；公司持續推動資安與制度強化，顯示以營運韌性與內控治理為主軸。。\n- 扣分或保留：簡報聲明指出，內容含前瞻性陳述，實際結果可能受**政治、經濟、市場**等因素影響。；2026Q1 衍生工具損益為負，顯示市場波動仍可能影響整體損益表現。；市占率部分項目下滑，包含經紀、電子交易、期貨IB與債券等，競爭壓力仍在。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
