          "detailMarkdown": "## 3680 家登 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 簡報揭露 2026 Q1 合併營收 NT$1,865,049 千元，年增；本年度淨利 NT$278,153 千元，EPS 2.54 元。\n- 轉錄提到 2025 全年營收 73.4 億元，較前年同期成長 12%；2026 年 1~4 月營收 27.5 億元，年增 20%。\n- 毛利率維持約 40%~45%區間；管理層歸因於產品組合變動、擴廠相關折舊與費用、原物料因素。\n- 產品結構方面，簡報顯示 2025 年光罩載具、晶圓載具、其他約為 53%、38%、9%；口述亦稱高毛利產品出貨占比變化影響毛利率。\n- 區域結構持續往海外與大中華分散，簡報揭露 2025 年本業營收地區占比以台灣為主，但海外比重逐步提升。\n\n### 展望與成長利基\n- 光罩載具方面，管理層提及 EUV 出貨動能延續，海外客戶需求在 2026 年前後持續增溫。\n- 晶圓載具方面，大中華市場回溫明確，管理層預期 2026 年營收較 2025 年顯著成長。\n- 先進封裝方面，尺寸規格逐步收斂，重點聚焦 300、310 與 510 等主流尺寸，管理層認為 2026 年起將逐步放量。\n- 航太方面，簡報與口述均指出 2025 年營收年增約 60%，2026 Q1 再年增 61%，美國產線預計 2026 Q4 開跑、2027 年正式量產。\n- 產能面管理層表示，P1/P2 互相支援後，整體產能可望提升，並提到近三年廠區規劃下供給無虞。\n\n### 產品、客戶與市場位置\n- 會議主軸為公司概況、三大產品線（光罩載具、晶圓載具、先進封裝）與航太事業進展。\n- 管理層強調 2025 年營收成長、2026 年 1~4 月延續成長，主要受先進製程與客戶資本支出帶動。\n- 產能與擴廠為主要背景，包括樹谷廠 P1/P2、昆山/重慶、日本久留米、美國子公司與家碩南科三期等。\n- 會中多次提到海外布局、在地供應與備援能力，以支撐大客戶需求。\n- 簡報與口述均強調產品組合升級與新產品導入，但部分數字口述與簡報存在差異，已列入「需人工確認」。\n- 毛利率維持約 40%~45%區間；管理層歸因於產品組合變動、擴廠相關折舊與費用、原物料因素。\n\n### 風險與不確定性\n- 擴廠與新產線投產時程仍受主管機關審查、建照/環評/水土保持等進度影響。\n- 美國與日本據點屬跨區域布局，存在建置、驗證、爬坡與在地供應鏈整合不確定性。\n- 毛利率受產品組合、設備折舊、擴廠費用、原物料價格與客戶議價影響，短期波動可能存在。\n- 先進封裝與航太相關新產線仍在驗證或試量產階段，量產節奏與客戶認證進度有變數。\n- 轉錄與簡報中部分數字、時點與名詞不一致，若引用需留意資料來源差異。\n- **需人工確認：** 口述提到「2026 年 4 月單月營收 86 億元」；簡報第 5 頁顯示「2026 1~4 月營業額 NT 27.5 億元」，兩者明顯不一致，可能為口誤或單位誤讀。\n- **需人工確認：** 轉錄中「嘉玲、嘉和副總、海博安財務長」等人名與簡報僅列發言人朱佳琳，其他高階主管姓名未於簡報明列。\n- **需人工確認：** 口述提及「覆合」「EUVPUSH」「KVS」等詞彙，可能為轉錄辨識誤差；簡報對應用語為「先進封裝」「EUV Pod」「CAPEX」。\n\n### Q&A 與管理層口氣\n- 產能與擴廠為主要背景，包括樹谷廠 P1/P2、昆山/重慶、日本久留米、美國子公司與家碩南科三期等。\n- 毛利率維持約 40%~45%區間；管理層歸因於產品組合變動、擴廠相關折舊與費用、原物料因素。\n- 產品結構方面，簡報顯示 2025 年光罩載具、晶圓載具、其他約為 53%、38%、9%；口述亦稱高毛利產品出貨占比變化影響毛利率。\n- 產能面管理層表示，P1/P2 互相支援後，整體產能可望提升，並提到近三年廠區規劃下供給無虞。\n- 美國與日本據點屬跨區域布局，存在建置、驗證、爬坡與在地供應鏈整合不確定性。\n- 毛利率受產品組合、設備折舊、擴廠費用、原物料價格與客戶議價影響，短期波動可能存在。\n\n### 評分利基點\n- 加分主因：管理層強調 2025 年營收成長、2026 年 1~4 月延續成長，主要受先進製程與客戶資本支出帶動。；會中多次提到海外布局、在地供應與備援能力，以支撐大客戶需求。；簡報與口述均強調產品組合升級與新產品導入，但部分數字口述與簡報存在差異，已列入「需人工確認」。。\n- 扣分或保留：擴廠與新產線投產時程仍受主管機關審查、建照/環評/水土保持等進度影響。；美國與日本據點屬跨區域布局，存在建置、驗證、爬坡與在地供應鏈整合不確定性。；毛利率受產品組合、設備折舊、擴廠費用、原物料價格與客戶議價影響，短期波動可能存在。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
