      "detailMarkdown": "## 2748 雲品 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（58 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 2、保守訊號 1。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1營收 776,929 仟元，年增 5%；稅後淨利 99,299 仟元，年減 8%；EPS 0.94 元。\n- 2025全年營收 2,424,910 仟元，稅後淨利 229,058 仟元，EPS 2.17 元。\n- 成本率約 66%～68%，毛利率約 32%～34%，營業費用率約 18%～20%。\n- 四大事業體營收占比：日月潭雲品溫泉酒店 38%、台北君品酒店 39%、館外餐飲 14%、委託經營管理 9%。\n- 股利政策圖示顯示公司維持現金股利配發政策；2025 年圖表中亦出現股票股利資訊，惟細節未完整揭露。\n\n### 展望與成長利基\n- 雲品酒店杭州預計 2026H2 營運，合約自開幕後起算 25 年，規劃 190 間客房與多元餐飲空間。\n- 米其林三星頤宮中餐廳將赴阿布達比設海外首店，預計 2026H2 開幕，規劃 150 席，鎖定高端客群。\n- 台灣委託經營案持續擴張，包含維多麗亞酒店、芳庭路壹號莊園、台南安平宜樂案、南投埔里福興溫泉、嘉義太保光禹野奢 Villa Resort 等。\n- 已營運或近期開幕案包括北町日式宿舍群、蘇卡利漫活、了了礁溪等，顯示委託經營版圖逐步成形。\n- 公司提及將持續推動永續發展、國際化布局與新商業模式調整。\n\n### 產品、客戶與市場位置\n- 高端餐飲與婚宴市場對景氣、旅遊需求、婚宴習慣與消費力變化較敏感。\n\n### 風險與不確定性\n- 海外案與新案多集中於 2026～2028 年，實際開幕時程、營運爬坡與客源導入仍具不確定性。\n- 高端餐飲與婚宴市場對景氣、旅遊需求、婚宴習慣與消費力變化較敏感。\n- 多數新案屬委託經營或合作模式，涉及合作方、場地條件與營運協作，執行複雜度較高。\n- 海外設點涉及法規、文化差異、供應鏈與人力配置，營運風險相對較高。\n- 部分專案仍在規劃或施工階段，未來資本支出與投資回收期未完整揭露。\n- **需人工確認**：簡報中公司創立時間為「101年11月22日／2012/11/22」，與公司沿革文字未見衝突，但仍建議以年報或主管機關資料再核對正式登記日。\n- **需人工確認**：簡報頁面寫「頤宮中餐廳連續八年(2018-2025) 榮獲米其林三星」，英文版寫法為 \"won three Micheline stars\"；建議確認「Micheline」是否為誤植，應為 Michelin。\n- **需人工確認**：台北君品酒店餐廳名稱在中英文版有差異（如「Ciao／Cial」、「亮廳／Banquet Grand Hall」等），可能為翻譯或簡報排版差異。\n\n### Q&A 與管理層口氣\n- 轉錄內容未提供，無法整理問答內容；未揭露。\n- 簡報另提及週休三日制度自 2024/9 起試行，目標在維持服務品質下改善人力與留任。\n- 簡報提及客房負碳排專案與碳權交易，顯示公司在 ESG 與碳管理上持續推進。\n- 2025 年永續獲獎項目多，包含旅遊永續、公司治理、人才發展與碳競爭力相關獎項。\n- 其他補充：公司簡介顯示員工人數 785 人、實收資本額約新台幣 1,057,787,400 元。\n\n### 評分利基點\n- 加分主因：管理層強調中長期方向為永續旅遊、營運模式優化、海外布局，以及持續擴大委託／合作經營業務。；簡報亦呈現ESG、股利政策與人才制度等非財務面內容，顯示公司希望強化品牌與營運模式延伸。；米其林三星頤宮中餐廳將赴阿布達比設海外首店，預計 2026H2 開幕，規劃 150 席，鎖定高端客群。。\n- 扣分或保留：海外案與新案多集中於 2026～2028 年，實際開幕時程、營運爬坡與客源導入仍具不確定性。；高端餐飲與婚宴市場對景氣、旅遊需求、婚宴習慣與消費力變化較敏感。；多數新案屬委託經營或合作模式，涉及合作方、場地條件與營運協作，執行複雜度較高。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
